public class Main {
    public static void main(String[] args) {
        int age = 8;
        String category;
        int price;

        if (age < 5) {
            category = "Infant";
            price = 0;
        } else if (age < 13) {
            category = "Child";
            price = 120;
        } else {
            category = "Adult";
            price = 250;
        }

        System.out.println(category + ": " + price);
    }
}

